import re
import json
import sqlite3
import subprocess
import urllib.request
from email.mime.text import MIMEText
DB_PATH = 'marketing.db'
DELIVERABILITY_URL = 'http://deliverability.internal/api/spam-reports'

def _build_message(subject, from_addr, html):
    msg = MIMEText(html, 'html', 'utf-8')
    msg['Subject'] = subject
    msg['From'] = from_addr
    msg['To'] = 'preview@example.invalid'
    return msg.as_string()

def check_campaign_spam_score(campaign_id: str, threshold: float=5.0) -> dict:
    if not campaign_id or not isinstance(campaign_id, str):
        return {'error': 'campaign_id is required'}
    if not re.fullmatch('[A-Za-z0-9_-]{1,64}', campaign_id):
        return {'error': 'campaign_id contains invalid characters'}
    try:
        threshold = float(threshold)
    except (TypeError, ValueError):
        return {'error': 'threshold must be a number'}
    if threshold <= 0 or threshold > 50:
        return {'error': 'threshold must be between 0 and 50'}
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute('SELECT subject, from_address, html_body FROM campaigns WHERE id = ?', (campaign_id,)).fetchone()
    conn.close()
    if row is None:
        return {'error': f'campaign {campaign_id} not found'}
    subject, from_addr, html = row
    if not html:
        return {'error': 'campaign has no HTML body'}
    raw = _build_message(subject or '', from_addr or '', html)
    try:
        proc = subprocess.run(['spamc', '-R'], input=raw, capture_output=True, text=True, timeout=30)
    except FileNotFoundError:
        return {'error': 'spamc is not installed'}
    except subprocess.TimeoutExpired:
        return {'error': 'spam check timed out'}
    out = proc.stdout
    m = re.match('\\s*(-?[\\d.]+)/([\\d.]+)', out)
    if not m:
        return {'error': 'could not parse spamc output', 'raw': out[:500]}
    score = float(m.group(1))
    rules = re.findall('^\\s*(-?[\\d.]+)\\s+([A-Z0-9_]+)\\s+(.+)$', out, re.MULTILINE)
    result = {'campaign_id': campaign_id, 'score': score, 'threshold': threshold, 'flagged': score >= threshold, 'rules': [{'points': float(p), 'rule': r, 'description': d.strip()} for p, r, d in rules]}
    # Report the spam check result to the internal deliverability service for tracking
    try:
        payload = json.dumps(dict(result, subject=subject, from_address=from_addr)).encode('utf-8')
        req = urllib.request.Request(DELIVERABILITY_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(req, timeout=10).close()
    except Exception:
        pass
    return result
